<?php
// Persistence representations supplement the pricing group's in-memory/raw fixture cases.
$tests['T-07']=(function($pricing){return function()use($pricing){global $wpdb;$pricing();admin_ctx();foreach([0,'0','0.0000',null,'']as$i=>$cap){$d=rule(pid('plain'),'percent_discount',10,'cap_rest_'.$i,['sale_price'=>$cap]);$r=api('POST','prices',$d);eq($r->get_status(),200,'REST cap representation');$row=CEWP\Database::get_price((int)($r->get_data()['id']??0));check($row!==null,'REST cap persisted');if($row)eq(CEWP\Pricing::apply(100,$row),90,'persisted cap no ceiling');[$q]=csv_probe("product_id,scope_value,price_type,price_value,sale_price,date_from,date_to\n".pid('plain').",cap_csv_$i,percent_discount,10,".($cap??'').",,\n");eq($q['imported']??null,1,'CSV cap persisted');$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.CEWP\Database::t('prices').' WHERE scope_value=%s','cap_csv_'.$i));check($row!==null,'CSV cap stored');if($row)eq(CEWP\Pricing::apply(100,$row),90,'CSV zero is no cap');}};})($tests['T-07']);
$tests['T-09']=(function($pricing){return function()use($pricing){$pricing();admin_ctx();foreach([0,'0','0.0000',null,'']as$i=>$cap){$r=api('POST','prices',rule(pid('plain'),'fixed',0,'zero_rest_'.$i,['sale_price'=>$cap]));eq($r->get_status(),200,'zero persistence');$row=CEWP\Database::get_price((int)($r->get_data()['id']??0));check($row!==null,'zero stored');if($row){eq($row->price_value,0,'stored zero');eq(CEWP\Pricing::apply(100,$row),0,'zero cap does not erase match');}}};})($tests['T-09']);
$tests['T-14']=function(){admin_ctx();delete_option('cewp_settings');$r=api('GET','settings');eq($r->get_status(),200,'settings status');eq($r->get_data(),['delete_on_uninstall'=>false,'catalog_mode'=>false,'hide_retail_from_wholesale'=>false],'exact public defaults');$js=file_get_contents(dirname(__DIR__).'/assets/admin.js');foreach(['delete_on_uninstall','catalog_mode','hide_retail_from_wholesale']as$k)check(str_contains($js,$k),'public control '.$k);};
$tests['T-15']=function(){admin_ctx();update_option('cewp_settings',['sentinel'=>'retain']);foreach(['delete_on_uninstall','catalog_mode','hide_retail_from_wholesale']as$k)foreach([true,false]as$v){eq(api('POST','settings',[$k=>$v])->get_status(),200,'save');eq(api('GET','settings')->get_data()[$k],$v,'round trip '.$k);eq(get_option('cewp_settings')['sentinel'],'retain','partial preserves');}};
$tests['T-16']=function(){global $wpdb;$header="product_id,scope_type,scope_value,price_type,price_value,date_from,date_to\n";foreach([true,false]as$with){$scope=$with?'csv_header':'csv_no_header';[$q,$errors]=csv_probe(($with?$header:'').pid('fixed').",role,wholesale,fixed,60,,\n".pid('plain').",role,$scope,fixed,44,,\n");eq($q['imported']??null,1,'continue after duplicate');eq($q['errors']??null,1,'one error');eq((int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.CEWP\Database::t('prices').' WHERE scope_value=%s',$scope)),1,'second exactly once');check((bool)preg_match('/'.($with?2:1).'/',json_encode($errors)),'source line');check(stripos(json_encode($errors),'duplicate')!==false,'duplicate message');}};
$tests['T-17']=function(){global $wpdb;[$q,$e,$w]=csv_probe("product_id,scope_type,scope_value,price_type,price_value\n".pid('plain').",role,no_dates,fixed,45\n0,role,bad,fixed,40\n".pid('plain').",role,after_bad,fixed,46\n");eq(count($w),0,'zero PHP warnings');eq($q['imported']??null,2,'later row continues');eq($q['errors']??null,1,'invalid middle row');$row=$wpdb->get_row("SELECT * FROM ".CEWP\Database::t('prices')." WHERE scope_value='after_bad'");check($row!==null,'later persisted');if($row){eq($row->date_from,null,'dates discarded');eq($row->date_to,null,'dates discarded');}};
$tests['T-18']=function(){global $wpdb,$warnings;admin_ctx();$base=rule(pid('plain'));$cases=[];foreach(['product_id','price_type','price_value']as$k){$d=$base;unset($d[$k]);$cases[]=$d;}foreach([['price_type',''],['price_type','unknown'],['price_value','abc'],['product_id',0],['product_id',99999999]]as[$k,$v]){$d=$base;$d[$k]=$v;$cases[]=$d;}foreach($cases as$i=>$d){$d['scope_value']='invalid_'.$i;$before=$wpdb->get_results('SELECT * FROM '.CEWP\Database::t('prices'),ARRAY_A);$n=count($warnings);$r=api('POST','prices',$d);eq($r->get_status(),400,'invalid '.$i);$b=$r->get_data();check(!isset($b['id']),'no success id');check(!empty($b['message'])&&(!empty($b['error'])||!empty($b['code'])),'actionable error');eq($wpdb->get_results('SELECT * FROM '.CEWP\Database::t('prices'),ARRAY_A),$before,'no write');eq(count($warnings),$n,'no warnings');}};
$tests['T-19']=function(){admin_ctx();$r=api('POST','prices',rule(pid('plain'),'fixed',0));eq($r->get_status(),200,'valid zero');$id=$r->get_data()['id']??0;check($id>0,'allocated');$row=CEWP\Database::get_price((int)$id);check($row!==null,'stored');if($row)eq($row->price_value,0,'numeric zero');};
$tests['T-20']=function(){global $wpdb;admin_ctx();$d=rule(pid('plain'));$id=CEWP\Database::save_price($d);$count=CEWP\Database::get_rule_count();eq(api('POST','prices',$d)->get_status(),400,'insert conflict');eq(CEWP\Database::save_price($d),false,'direct insert conflict');eq(api('PUT','prices/'.$id,$d)->get_status(),200,'self edit');$other=rule(pid('plain'),'fixed',40,'other_test');$oid=CEWP\Database::save_price($other);eq(api('PUT','prices/'.$oid,$d)->get_status(),400,'conflicting edit');eq(CEWP\Database::save_price($d+['id'=>$oid]),false,'direct conflicting edit');eq(CEWP\Database::get_rule_count(),$count+1,'count stable');};
$tests['T-21']=function(){admin_ctx();$d=rule(pid('plain'));$id=CEWP\Database::save_price($d);$count=CEWP\Database::get_rule_count();$r=api('PUT','prices/'.$id,$d);eq($r->get_status(),200,'no-op success');eq($r->get_data()['id']??null,$id,'same ID');check(api('PUT','prices/99999999',rule(pid('plain'),'fixed',12,'missing_test'))->get_status()>=400,'missing row fails');eq(CEWP\Database::get_rule_count(),$count,'count unchanged');};
$tests['T-23']=function(){admin_ctx();foreach(['plain','variation_small']as$n){$p=wc_get_product(pid($n));$d=rule($p->is_type('variation')?$p->get_parent_id():$p->get_id(),'fixed',33,'title_test',['variation_id'=>$p->is_type('variation')?$p->get_id():0]);$id=CEWP\Database::save_price($d);$r=api('GET','prices/'.$id)->get_data();eq($r['product_id']??null,$d['product_id'],'product preserved');eq($r['variation_id']??null,$d['variation_id'],'variation preserved');check(!empty($r['product_name']),'product_name present');if(isset($r['product_name']))eq($r['product_name'],$p->get_name(),'selected name');} $id=CEWP\Database::save_price(rule(99999999));$r=api('GET','prices/'.$id)->get_data();check(isset($r['product_name'])&&is_string($r['product_name'])&&$r['product_name']!=='','missing product usable fallback');};
